// Wall decor gắn tường bắc
function wallZ(x,y){let best=null;for(const b of SH.blds){if(!(x>b.x0&&x<b.x1&&y>b.y0&&y<b.y1+.5))continue;for(const w of b.Wl){if(w[1]-w[0]<w[3]-w[2])continue;if(x<w[0]||x>w[1]||w[3]>y+.1)continue;if(best==null||w[3]>best)best=w[3]}}return best}
const FUR=new Map();
function buildFur(f){
 const k=f[0],x=f[1],y=f[2],tw=SW[k]||(AS[k]&&AS[k].tw)||1.2;
 if(x>=1390&&STOREM[k]){const g=new T.Group();g.position.set(x,0,y);STOREM[k](g,tw);scene.add(g);return{g}}
 if(MODELS[k]||M3[k]){const g=new T.Group();g.position.set(x,0,y);(MODELS[k]||M3[k])(g,tw,x,y);scene.add(g);
  if(k=='f_bed1'||k=='f_bed2'){const w=k=='f_bed1'?1.55:2.15,len=k=='f_bed1'?2.3:2.35;const c={x0:x-w/2,x1:x+w/2,z0:y-len,z1:y-.75,on:false,v25:1};SH.cols.push(c);EXTRA.push(c)}
  if(k=='f_dtab'){const c={x0:x-1.1,x1:x+1.1,z0:y-1.52,z1:y-.75,on:false,v25:1};SH.cols.push(c);EXTRA.push(c)}
  return{g}}
 if(WALLDECO[k]){const z=wallZ(x,y),t=texK(k);if(z!=null&&t){const a=AS[k],w=tw,h=w*a.h/a.w,m=new T.Mesh(new T.PlaneGeometry(w,h),cardMat(t));const cy=Math.min(WALLDECO[k],2.95-h/2);m.position.set(x,cy,z+.03);scene.add(m);return{g:m}}}
 const t=texK(k);if(!t)return null;const a=AS[k],cd=card(t,tw,tw*a.h/a.w,x,y);if(inMallXY(x,y)||inHospXY(x,y)){const hsp=!inMallXY(x,y);cd.material=cd.material.clone();cd.material.color.setHex(hsp?0xc4beb2:0x8f897e);const h=Math.sin(x*12.9+y*7.1);if(h>.55)cd.rotation.z=(h-.55)*.5}return{g:cd}}

