const ghost=new T.Mesh(cardGeo,new T.MeshBasicMaterial({map:ply.t,transparent:true,opacity:.38,color:0x9fd4ff,depthWrite:false,depthFunc:T.GreaterDepth,alphaTest:.3}));
ghost.renderOrder=999;scene.add(ghost);
const DYN2A=(()=>{let on=true;try{on=localStorage.getItem('sh_dyn2a')!=='0'}catch(e){}
 const SAFE=new Set(['save','restore','translate','scale','rotate','setTransform','transform','resetTransform','beginPath','closePath','moveTo','lineTo','arc','arcTo','ellipse','rect','roundRect','quadraticCurveTo','bezierCurveTo','fill','stroke','fillRect','strokeRect','clearRect','drawImage','fillText','strokeText','clip','setLineDash']);
 const ids=new WeakMap();let nid=1,uq=0;
 const tok=x=>{const t=typeof x;if(t==='number'||t==='boolean'||x==null)return''+x;if(t==='string')return JSON.stringify(x);if(Array.isArray(x))return'['+x.map(tok).join(',')+']';
  if(typeof HTMLImageElement!=='undefined'&&x instanceof HTMLImageElement&&x.complete&&x.naturalWidth){let v=ids.get(x);if(!v){v=nid++;ids.set(x,v)}return'I'+v}
  return'!'+(++uq)};// canvas, gradient, Path2D, ảnh chưa tải xong… có thể đổi nội dung → luôn coi là khác
 const ST={vẽLại:0,bỏQua:0,trựcTiếp:0};
 function draw(d,z,fn){if(!on){SH.off(d.c,z,fn);d.t.needsUpdate=true;ST.trựcTiếp++;return}
  const real=d.c.getContext('2d'),ops=[];let pass=false;
  const play=o=>{if(o[0]==='=')real[o[1]]=o[2];else real[o[0]](...o[1])};
  const goPass=()=>{if(!pass){pass=true;for(const o of ops)play(o);ops.length=0}};
  const rec=new Proxy({},{get(_,k){if(k==='canvas')return d.c;const v=real[k];
    if(pass)return typeof v==='function'?v.bind(real):v;
    if(typeof v==='function')return SAFE.has(k)?(...a)=>{if(pass)real[k](...a);else ops.push([k,a])}:(...a)=>{goPass();return real[k](...a)};
    goPass();return v},
   set(_,k,v){if(pass)real[k]=v;else ops.push(['=',k,v]);return true}});
  const gc=d.c.getContext;d.c.getContext=()=>rec;try{SH.off(d.c,z,fn)}finally{d.c.getContext=gc}
  if(pass){d.k2a=null;d.t.needsUpdate=true;ST.trựcTiếp++;return}
  let key='';for(const o of ops)key+=(o[0]==='='?'='+o[1]+':'+tok(o[2]):o[0]+'('+o[1].map(tok).join(',')+')')+';';
  if(key===d.k2a){ST.bỏQua++;return}
  for(const o of ops)play(o);d.k2a=key;d.t.needsUpdate=true;ST.vẽLại++}
 return{draw,ST,get on(){return on},set on(v){on=v}}})();
