V.espr=(g,e,x,y,t,Zs)=>{if(!EATL.complete||!EATL.naturalWidth)return false;
 const lx=e._lx==null?e.x:e._lx,ly=e._ly==null?e.y:e._ly,dx=e.x-lx,dy=e.y-ly;e._lx=e.x;e._ly=e.y;
 if(Math.hypot(dx,dy)>.0004){e._dir=Math.abs(dx)>Math.abs(dy)*.9?(dx>0?0:1):(dy<0?2:3);e._mt=t}
 if(e.cd>.97&&(e._lcd==null||e._lcd<.9))e._hitT=t;e._lcd=e.cd;
 let row=e._dir==null?3:e._dir,fi=t-(e._mt||-1e9)<180?Math.floor(t/90+(e.p||0)*7)%8:0;
 if(e.cd>.45&&e.cd<=1&&e._hitT!=null&&t-e._hitT<600){const px=SH.pos.x-e.x,py=SH.pos.y-e.y;row=4+(Math.abs(px)>Math.abs(py)?(px>0?2:3):(py<0?0:1));fi=Math.min(7,Math.floor((t-e._hitT)/75))}
 const h=Zs*3.4*(ECH/150),w=h*ECW/ECH,sh=e.kb>0?Math.sin(t/25)*Zs*.08:0;
 g.save();g.globalAlpha=.3;g.fillStyle='#000';g.beginPath();g.ellipse(x,y,Zs*.6,Zs*.2,0,0,7);g.fill();g.restore();
 g.save();g.globalAlpha=.35+.2*Math.sin(t/200);g.fillStyle='#ff2040';g.beginPath();g.ellipse(x,y,Zs*.75,Zs*.25,0,0,7);g.fill();g.restore();
 g.drawImage(EATL,fi*ECW,row*ECH,ECW,ECH,x-w/2+sh,y-h+Zs*.12,w,h);
 const bw=Zs*1.2,bh=Zs*.18,by=y-h*.86,bx=x-bw/2,f=Math.max(0,e.hp)/e.mhp;
 g.fillStyle='rgba(0,0,0,.75)';g.fillRect(bx-1,by-1,bw+2,bh+2);g.fillStyle='#4a1010';g.fillRect(bx,by,bw,bh);g.fillStyle='#ff3050';g.fillRect(bx,by,bw*f,bh);
 g.save();g.font='bold '+Math.round(Zs*.24)+'px system-ui';g.textAlign='center';g.fillStyle='#ffd24a';g.fillText('★ Tinh anh '+Math.ceil(Math.max(0,e.hp))+'/'+e.mhp,x,by-Zs*.06);g.restore();return true};

const MINE=new Map(),ROCK_KEYS7=new Map(),removedMineKeys10=new Set();
const ROCK_HOURS7=24,isRock7=r=>/^(rock[123]|hrk[1-5])$/.test(r.hk||r[0]),rockKey7=r=>'r'+r[1].toFixed(1)+r[2].toFixed(1);
// Keep the existing coordinate-based mining keys, so old saves and chunk reloads retain depletion.
function refreshRocks7(){if(!SH.F5?.rockGone)return;for(const r of SH.ROCKS){if(!isRock7(r))continue;if(!r.col){const x=r[1],z=r[2],w=r[3];r.col=SH.cols.find(c=>!c.c17&&!c.ft&&Math.abs((c.x0+c.x1)/2-x)<.001&&Math.abs(c.z1-z)<.001&&Math.abs((c.x1-c.x0)-w*.76)<.01)}const st=MINE.get(rockKey7(r));if(st&&st.n<=0&&SH.GT-st.t>=ROCK_HOURS7)st.n=3;const gone=!!st&&st.n<=0;if(gone!==!!r.gone||gone&&r.col?.on!==false)SH.F5.rockGone(r,gone)}}
V.rockLifecycle={refresh:refreshRocks7,respawnHours:ROCK_HOURS7,remap(from,to){for(const[k,v]of ROCK_KEYS7)if(v===from)ROCK_KEYS7.set(k,to);ROCK_KEYS7.set(from,to);if(MINE.has(from)){if(!MINE.has(to))MINE.set(to,MINE.get(from));MINE.delete(from)}}};
setInterval(refreshRocks7,1000);
function mineAt(key,uses,label,respawn=48,actor=null){const S_=actor?actor.inv:SH.S;if(!(actor?actor.pick:S_.pick))return SH.say('⛏ Cần cuốc chim – chế tạo ở 🔨 bàn chế tạo trong nhà gỗ');if(!actor&&SH.F5&&SH.F5.tool)SH.F5.tool('mine');let st=MINE.get(key);const gt=SH.GT;if(!st){st={n:uses,t:-1e9};MINE.set(key,st)}
 if(st.n<=0){const hours=respawn;if(gt-st.t>=hours)st.n=uses;else return SH.say('⛏ Chỗ này đã đào hết, quay lại sau ~'+Math.ceil(hours-(gt-st.t))+' giờ')}
 const n=2+Math.floor(Math.random()*3),a=actor?(actor.inv.stone=(actor.inv.stone||0)+n,n):SH.give('stone',n);if(!a)return SH.say('🎒 Túi đầy!');st.n--;if(st.n<=0)st.t=gt;if(!actor)SH.say('⛏ Đào được '+a+' đá'+(label?' ('+label+')':''));return{ok:true,amount:a,depleted:st.n<=0}}
