function lidOpen(s){const K=[[0,0],[1.2,0],[1.7,.28],[2.0,.05],[2.6,.55],[2.85,.3],[3.6,1]];for(let i=1;i<K.length;i++)if(s<K[i][0]){const a=K[i-1],b=K[i],k=ease((s-a[0])/(b[0]-a[0]));return a[1]+(b[1]-a[1])*k}return 1}
