  ply.m.visible=k>.55;if(k>.55){DYN2A.draw(ply,PZ,()=>SH.player(ply.ax,ply.ay,t));placeDyn(ply,pos.x,pos.y+.02);if(SH.lowDyn)SH.lowDyn(ply.m,pos.x,pos.y);ply.m.material.opacity=Math.min(1,(k-.55)*3)}
