function frame(t,dt){
 refreshRocks7();
 if(!S.on&&!S.dead){cv3.style.display='none';SH.draw2d(t,dt);return}
 if(INTRO.pending&&V.on)startIntro(t);
 if(INTRO.active){cv3.style.display='block';try{introFrame(t,dt)}catch(e){console.error('[intro]',e);introFinish()}return}
 cv3.style.display='block';
 try{frame3(t,dt);errs=0}catch(e){console.error('[2.5D]',e);if(++errs>3){setMode(false);SH.say('⚠️ Lỗi 2.5D – đã chuyển về 2D')}SH.draw2d(t,dt)}}
function frame3(t,dt){if(!globalThis.Z21_READY)return;
 const Wv=innerWidth,Hv=innerHeight,Zv=SH.Z,ih=SH.IH();
 // camera mượt
 const lyo=(()=>{const f=SH.HO2&&SH.HO2.fall;if(!f||ih)return 0;const dx=Math.abs(pos.x-f.x),dy=pos.y-f.y;if(dx>13||dy<0||dy>16)return 0;return -3.6*Math.min(1,(13-dx)/5)*Math.min(1,dy/3,(16-dy)/5)})(); // nhìn xa hơn về phía thác khi tới gần
 if(Math.hypot(pos.x-camX,pos.y-camY)>14||ih!==lastIH){camX=pos.x;camY=pos.y+lyo}else{const k=1-Math.exp(-dt*9);camX=lerp(camX,pos.x,k);camY=lerp(camY,pos.y+lyo,k*.6)}lastIH=ih;
 const hw=Wv/2/Zv,hh=Hv/2/Zv;cam.left=-hw;cam.right=hw;cam.top=hh;cam.bottom=-hh;cam.updateProjectionMatrix();
 const EV=globalThis.ELEV38&&ELEV38.on?ELEV38:null,ch=EV?EV.camH(dt,pos.x,pos.y,ih):0,ep=EV?EV.pad(camX,camY):0;// ELEV38: camera dâng theo độ cao chỗ đứng
 cam.position.set(camX,SN*300+ch,camY+CS*300);cam.lookAt(camX,ch,camY);
 GTL.ep=ep;groundUpd(t,camX,camY,Wv,Hv,Zv);
 const vx0=camX-hw-2,vx1=camX+hw+2,vy0=camY-hh/SN-2-ep,vy1=camY+hh/SN+2+ep;
 if(!cabin){buildCabinInterior();buildMts()}
 updWorld(t,vx0,vx1,vy0,vy1);updWalls();buildCity();updCity(vx0,vx1,vy0,vy1);updGas();updLake(t);updDome(t);updForest(t,vx0,vx1,vy0,vy1);updF4(t,vx0,vx1,vy0,vy1);updF5(t,vx0,vx1,vy0,vy1);try{updHo(t,vx0,vx1,vy0,vy1)}catch(e){if(!HOM.err){HOM.err=1;console.warn('[2.5D] hồ',e)}}try{if(globalThis.W15&&W15.upd3)W15.upd3(t,vx0,vx1,vy0,vy1)}catch(e){if(!HOM.w15){HOM.w15=1;console.warn('[2.5D] W15',e)}}
 // cửa căn nhà gỗ
 {if(cabin.stv){cabin.stv.visible=!!SH.S.stove;if(cabinStoveC)cabinStoveC.on=V.on&&!!SH.S.stove}const d=SH.door,dg=cabin.door;dg.visible=!d.broken;cabin.doorL.rotation.y=d.locked?0:-Math.PI/2;cabin.doorR.rotation.y=d.locked?0:Math.PI/2;cabSync();const CO=globalThis.CO||{x:0,y:0};cabin.doorL.position.z=cabin.doorR.position.z=SH.cab.y1-CO.y-.22;cabin.g.visible=!CO.none&&Math.abs(camX-CO.x)<hw+10&&Math.abs(camY-CO.y)<hh/SN+12}
 // ánh sáng ngày/đêm
 const dd=.5+.5*Math.cos((S.h-13)/12*Math.PI),a=clamp((.62-dd)*1.5,0,.78),L=1-a*.08;/* L32: bóng tối đêm do lớp phủ 10 m (don31) đảm nhiệm → cảnh 3D trong vùng sáng không bị tối thêm, nhân vật sáng rõ */
 amb.intensity=.22+.52*L;amb.color.setRGB(lerp(.55,1,L),lerp(.6,1,L),lerp(.95,1,L));sun.intensity=.46*L;
 pLight.intensity=a>.05?1.5*a/.78:0;pLight.position.set(pos.x,1.8,pos.y+.6);cLight.intensity=a>.05&&!ih?1.3*a/.78:0;
 if(ih){const f=SH.curFl();if(f&&f.xb&&f.xb.spr==='hosp'){amb.intensity*=.85;amb.color.setRGB(.88,.9,.94);const fl=Math.sin(t*.011)+Math.sin(t*.027)>1.85?.4:1;pLight.intensity=Math.max(pLight.intensity,.5*fl)}if(f&&f.xb&&f.xb.spr==='tttm'){amb.intensity*=.62;amb.color.setRGB(.72,.76,.86);sun.intensity*=.35;const fl=Math.sin(t*.013)+Math.sin(t*.031)>1.6?.25:1;pLight.intensity=Math.max(pLight.intensity,.95*fl)}}
 // người chơi
 const ly=SH.lying;
 if(ly){ply.m.visible=false;ghost.visible=false;lying(t,ly)}else{lyMesh.visible=false;ply.m.visible=true;ghost.visible=true;
  DYN2A.draw(ply,PZ,()=>SH.player(ply.ax,ply.ay,t));placeDyn(ply,pos.x,pos.y+.02);if(SH.lowDyn)SH.lowDyn(ply.m,pos.x,pos.y);ply.m.material.transparent=true;ply.m.material.opacity=V.hid?.5:1;ghost.position.copy(ply.m.position);ghost.scale.copy(ply.m.scale)}
 // zombie / quái
 const seen=new Set();
 for(const e of SH.ens){if(!inView(e.x,e.y,vx0,vx1,vy0,vy1+4))continue;seen.add(e);let d=ENS.get(e);if(!d){d=dynSprite(4,4.2,.6,40);ENS.set(e,d)}d.m.visible=true;DYN2A.draw(d,40,()=>SH.en(e,d.ax,d.ay,t));placeDyn(d,e.x,e.y);if(SH.lowDyn)SH.lowDyn(d.m,e.x,e.y)}
 for(const[e,d]of ENS)if(!seen.has(e)){scene.remove(d.m);d.t.dispose();d.m.material.dispose();ENS.delete(e)}
 // người chơi khác (online)
 const so=new Set();
 for(const k in SH.OTH){const o=SH.OTH[k];if(o.tx==null||!o.on)continue;o.vx=(o.tx-o.x)*Math.min(1,dt*8);o.vy=(o.ty-o.y)*Math.min(1,dt*8);o.x+=o.vx;o.y+=o.vy;if(!inView(o.x,o.y,vx0,vx1,vy0,vy1+4))continue;so.add(k);let d=OTHS.get(k);if(!d){d=dynSprite(4,4.2,.7,56);OTHS.set(k,d)}DYN2A.draw(d,56,()=>SH.other(o,d.ax,d.ay));placeDyn(d,o.x,o.y)}
 for(const[k,d]of OTHS)if(!so.has(k)){scene.remove(d.m);d.t.dispose();OTHS.delete(k)}
 dqTick();if(EV)EV.pre(scene);try{R.render(scene,cam)}finally{if(EV)EV.post()}
 SH.hud(t,dt,camX,camY,SN,hudFn);
}
function lying(t,ly){
 const u=ly.u,bd=BEDS.get(bkey(u.x,u.y))||{cx:u.x,zHead:u.y-2.3,len:2.3,top:.64};
 const SL=SH.SLF();let img=null,ar=.8;
 if(SL){img=SL[Math.floor(t/380)%SL.length];ar=1.6/1.99}
 else{const f=SH.SETS[SH.CH]&&SH.SETS[SH.CH].idle&&SH.SETS[SH.CH].idle[0];if(f&&f.i&&f.i.complete&&f.i.naturalWidth){img=f.i;ar=f.w/f.h}}
 if(!img){lyMesh.visible=false;return}
 const tex=texImg(img);if(lyMesh.material.map!==tex){lyMesh.material.map=tex;lyMesh.material.needsUpdate=true}
 const len=Math.min(2.3,bd.len-.08),w=len*ar,br=Math.sin(t/1000*2.4);
 lyMesh.scale.set(w*(1+.022*br),1,len*(1+.008*br)); // thở nhẹ
 lyMesh.position.set(bd.cx,bd.top+.11+.012*br,bd.zHead+.06+len/2);lyMesh.visible=true}

