/* ===== BƯỚC 4: RỪNG CỔ THỤ HỒ ÁNH NGUYỆT (lớp bổ sung, ID ổn định, không dời cây/vật phẩm cũ) ===== */
var FOREST; // (không gán null: forestPlan chạy trước dòng này)
function forestPlan(){
 const F=FOREST={trees:[],rocks:[],bush:[],flow:[],trails:[],built:false};
 const Zr=(SH.ZN.find(z=>z.n=='Hồ Ánh Nguyệt')||{}).r,L=SH.LAKES[0];if(!Zr||!L||L.t!=='w')return;
 const R=srng(4401977);
 const inZ=(x,y,m)=>x>Zr[0]+m&&x<Zr[2]-m&&y>Zr[1]+m&&y<Zr[3]-m;
 const segD=(x,y,p)=>{let m=1e9;for(let i=1;i<p.length;i++){const a=p[i-1],b=p[i],vx=b[0]-a[0],vy=b[1]-a[1],l2=vx*vx+vy*vy||1,tt=clamp(((x-a[0])*vx+(y-a[1])*vy)/l2,0,1);m=Math.min(m,Math.hypot(x-a[0]-vx*tt,y-a[1]-vy*tt))}return m};
 const trailD=SH.pathD?(x,y)=>SH.pathD(x,y,7)+.7:(x,y)=>{let m=1e9;for(const p of F.trails)m=Math.min(m,segD(x,y,p.pts));for(const p of LK.paths)m=Math.min(m,segD(x,y,p));return m};
 const lakeD=SH.lkDist?(x,y)=>SH.inLk(x,y)?-1:SH.lkDist(x,y):(x,y)=>{let m=1e9;for(const l of SH.LAKES)m=Math.min(m,Math.hypot(x-l.x,y-l.y)-l.r);return m};
 const colNear=(x,y,r)=>SH.cols.some(c=>x>c.x0-r&&x<c.x1+r&&y>c.z0-r&&y<c.z1+r);
 const bldNear=(x,y,r)=>SH.blds.some(b=>b.x0<INT_X0&&x>b.x0-r&&x<b.x1+r&&y>b.y0-r&&y<b.y1+r);
 const lkObj=(x,y,r)=>[...LK.rocks,...LK.hides,...LK.rice,...LK.melon].some(q=>Math.hypot(q.x-x,q.y-y)<q.r+r);
 // --- đường mòn: vòng ven hồ (bỏ đoạn sát mép vùng phía đông) + 4 nhánh uốn lượn xuyên rừng ---
 if(SH.HOD){for(const p of SH.HOD.paths){if(p.kind=='spur')continue;let run=[];const flush=()=>{if(run.length>3)F.trails.push({id:'fp'+F.trails.length,pts:run,w:p.w/2});run=[]};p.pts.forEach((q,i)=>{if(i%2)return;if(Math.hypot(q[0]-L.x,q[1]-L.y)<52)run.push(q);else flush()});flush()}}
 else{const RS=L.r+2.3;{const pts=[];for(let a=.55;a<=Math.PI*2-.55+1e-6;a+=.18){const r=RS+Math.sin(a*3.1)*.5+Math.sin(a*7.3)*.25;pts.push([L.x+Math.cos(a)*r,L.y+Math.sin(a)*r])}F.trails.push({id:'fp0',pts,w:.62})}
 const wig=(a,b,amp,ph)=>{const dx=b[0]-a[0],dy=b[1]-a[1],l=Math.hypot(dx,dy)||1,nx=-dy/l,ny=dx/l,n=Math.max(4,Math.ceil(l/2)),pts=[];
  for(let i=0;i<=n;i++){const t=i/n,w=(Math.sin(t*Math.PI*2.2+ph)*amp+Math.sin(t*Math.PI*5.3+ph*1.7)*amp*.3)*Math.sin(t*Math.PI);pts.push([a[0]+dx*t+nx*w,a[1]+dy*t+ny*w])}return pts};
 [[-1.62,2.2,1.1],[-2.55,1.8,2.3],[2.8,2.4,.4],[1.38,1.6,3.1]].forEach(([ang,amp,ph],i)=>{let r=27,o=null;while(r>16){const x=L.x+Math.cos(ang)*r,y=L.y+Math.sin(ang)*r;if(inZ(x,y,2.5)&&!bldNear(x,y,2)){o=[x,y];break}r-=1}
  if(!o)return;const s=[L.x+Math.cos(ang+.12)*RS,L.y+Math.sin(ang+.12)*RS];F.trails.push({id:'fp'+(i+1),pts:wig(o,s,amp,ph),w:.55})});}
 // --- hai bên đường: hoa dại & cỏ sát mép, bụi rậm phía sau, đá lớn phủ rêu xa hơn ---
 const okDecor=(x,y,minT)=>inZ(x,y,1)&&lakeD(x,y)>.9&&trailD(x,y)>minT&&!colNear(x,y,.35)&&!bldNear(x,y,1)&&!lkObj(x,y,.6)&&Math.hypot(x,y-1)>11;
 for(const tr of F.trails){const p=tr.pts;for(let i=1;i<p.length;i++){const a=p[i-1],b=p[i],dx=b[0]-a[0],dy=b[1]-a[1],l=Math.hypot(dx,dy)||1,nx=-dy/l,ny=dx/l,n=Math.max(1,Math.round(l/1.25));
  for(let j=0;j<n;j++){const t=(j+R())/n,cx=a[0]+dx*t,cy=a[1]+dy*t;for(const sd of[-1,1]){
   if(R()<.6){const o=1.05+R()*.45,x=cx+nx*sd*o,y=cy+ny*sd*o;if(okDecor(x,y,.85))F.flow.push({id:'ff'+F.flow.length,x,y,k:Math.floor(R()*3),w:.7+R()*.45})}
   if(R()<.42){const o=1.9+R()*.7,x=cx+nx*sd*o,y=cy+ny*sd*o;if(okDecor(x,y,1.5))F.bush.push({id:'fb'+F.bush.length,x,y,k:['bush2','bush3','bush4'][Math.floor(R()*3)],w:.55+R()*.5})}}}
  for(let s=4;s<p.length;s+=4)if(R()<.6){const k=Math.min(p.length-1,s),q=p[k-1],w=p[k],dx=w[0]-q[0],dy=w[1]-q[1],l=Math.hypot(dx,dy)||1,sd=R()<.5?-1:1,o=3.3+R()*1.1,x=w[0]-dy/l*sd*o,y=w[1]+dx/l*sd*o,sz=.9+R()*1.1;
   if(okDecor(x,y,2.6)&&!F.rocks.some(r=>Math.hypot(r.x-x,r.y-y)<4))F.rocks.push({id:'fr'+F.rocks.length,x,y,s:sz})}}}
 // --- cây cổ thụ: nhiều cỡ, chừa khoảng trống, không đè cây/vật cũ, khe giữa thân cây đủ rộng để đi qua ---
 const keys=['tree1','tree2','tree3','tree4'].filter(k=>SH.AS[k]);if(!keys.length)keys.push('tree1');
 for(let k=0;k<6000&&F.trees.length<210;k++){const a=R()*Math.PI*2,r=L.r+3.2+Math.pow(R(),.8)*27,x=L.x+Math.cos(a)*r,y=L.y+Math.sin(a)*r;
  const q=R(),s=q<.42?2.4+R()*1.3:q<.8?1.5+R()*.8:1+R()*.4,h=.22*s+.12;
  if(!inZ(x,y,1.2+h))continue;if(Math.sin(x*.23+1.3)*Math.cos(y*.19-.7)+Math.sin((x+y)*.11)<-.85)continue; // khoảng trống tự nhiên
  if(trailD(x,y)<2.1+s*.35||lakeD(x,y)<2.4+s*.3||Math.hypot(x,y-1)<13)continue;
  if(colNear(x,y,h+1)||bldNear(x,y,2)||lkObj(x,y,1.2+h))continue;
  if(SH.trees.some(t=>t.hp>0&&Math.abs(t.x-x)<3&&Math.abs(t.y-y)<3&&Math.hypot(t.x-x,t.y-y)<1.5+s*.4))continue;
  if(F.rocks.some(o=>Math.hypot(o.x-x,o.y-y)<o.s+h+1.4))continue;
  if(F.trees.some(o=>Math.hypot(o.x-x,o.y-y)<(o.s+s)*.47+1.15))continue;
  F.trees.push({id:'ft'+F.trees.length,x,y,s,sp:keys[Math.floor(R()*keys.length)],h})}
 for(const o of F.trees){const c={x0:o.x-o.h,x1:o.x+o.h,z0:o.y-o.h*.6,z1:o.y+o.h*.5,on:false,v25:1,ft:1};SH.cols.push(c);EXTRA.push(c);o.col5=c}
 for(const r of F.rocks){const s=r.s*.7;const c={x0:r.x-s,x1:r.x+s,z0:r.y-s*.55,z1:r.y+s*.4,on:false,v25:1,ft:1};SH.cols.push(c);EXTRA.push(c);r.col5=c}
 forestBounds();V.forest=F}
function syncForest5(F){if(!globalThis.CITY5_DATA||!globalThis.Z21_READY||!F||F.sync5)return;F.sync5=1;for(const k of['trees','rocks','bush','flow'])for(const o of F[k]){const q=Z21M(o.x,o.y);o.x=q[0];o.y=q[1];if(o.col5){const h=k==='trees'?o.h:o.s*.7;Object.assign(o.col5,{x0:o.x-h,x1:o.x+h,z0:o.y-h*(k==='trees'?.6:.55),z1:o.y+h*(k==='trees'?.5:.4)})}}for(const t of F.trails)for(const p of t.pts){const q=Z21M(p[0],p[1]);p[0]=q[0];p[1]=q[1]}forestBounds();SH.colsDirty()}
V.syncForest5=()=>syncForest5(FOREST);
